CREATE OR REPLACE FUNCTION public.review_kivra_saas_transfer(p_submission_id bigint,p_superadmin_id integer,p_approve boolean,p_notes text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN IF p_approve IS NULL THEN RAISE EXCEPTION 'Decisión inválida'; END IF; RETURN public.review_kivra_saas_transfer(p_submission_id,p_superadmin_id,CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END::text,p_notes); END; $$;
